function pulauRegionPage(r) { return geoRegionPage(r, pl, 'pulau', PULAU_CFG); }
function pulauPage(i, sum) { return geoItemPage(i, sum, pl, 'pulau', PULAU_CFG); }
function pulauNotFound(q) { return geoNotFound('pulau', PULAU_CFG, q); }
